/**
 * Generated by `createschema news.OrganizationNewsItem 'organization:Relationship:Organization:CASCADE; title:Text; body:Text; type:Select:common,emergency'`
 */

const dayjs = require('dayjs')
const { get, isEmpty } = require('lodash')

const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')
const { find, getById } = require('@open-condo/keystone/schema')

const { canReadObjectsAsB2BAppServiceUser, canManageObjectsAsB2BAppServiceUser } = require('@condo/domains/miniapp/utils/b2bAppServiceUserAccess')
const { queryFindNewsItemsScopesByResidents } = require('@condo/domains/news/utils/accessSchema')
const {
    getEmployedOrRelatedOrganizationsByPermissions,
    checkPermissionsInEmployedOrRelatedOrganizations,
} = require('@condo/domains/organization/utils/accessSchema')
const { getUserResidents } = require('@condo/domains/resident/utils/accessSchema')
const { RESIDENT, SERVICE } = require('@condo/domains/user/constants/common')

async function canReadNewsItems (args) {
    const { authentication: { item: user }, context } = args
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    if (user.isAdmin || user.isSupport) return {}

    if (user.type === SERVICE) {
        return await canReadObjectsAsB2BAppServiceUser(args)
    }

    if (user.type === RESIDENT) {
        const residents = await getUserResidents(context, user)
        if (isEmpty(residents)) return false

        const organizationsIds = residents.map((resident) => resident.organization)
        const scopesCondition = queryFindNewsItemsScopesByResidents(residents)

        return {
            isPublished: true,
            organization: { id_in: organizationsIds },
            scopes_some: scopesCondition,
            sendAt_lte: dayjs().toISOString(),
        }
    }

    const permittedOrganizations = await getEmployedOrRelatedOrganizationsByPermissions(context, user, 'canReadNewsItems')

    // access for staff
    return {
        organization: {
            id_in: permittedOrganizations,
        },
    }
}

async function canManageNewsItems (args) {
    const { authentication: { item: user }, context, originalInput, operation, itemId } = args
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isAdmin || user.isSupport) return true
    if (user.type === RESIDENT) return false

    if (user.type === SERVICE) {
        return await canManageObjectsAsB2BAppServiceUser(args)
    }

    let organizationId

    if (operation === 'create') {
        organizationId = get(originalInput, ['organization', 'connect', 'id'])
    } else if (operation === 'update') {
        if (!itemId) return false
        const newsItem = await getById('NewsItem', itemId)
        organizationId = get(newsItem, 'organization', null)
    }

    if (!organizationId) return false

    return await checkPermissionsInEmployedOrRelatedOrganizations(context, user, organizationId, 'canManageNewsItems')
}

function canDirectlySetNewsItemSource ({ authentication: { item: user } }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    // The news form never sends "source", so it always falls back to the default one via resolveInput.
    // Only a trusted SERVICE account (b2b app backend, via an authoritative bulk mutation) or an admin
    // is allowed to explicitly set a non-default source.
    return user.isAdmin || user.type === SERVICE
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canReadNewsItems,
    canManageNewsItems,
    canDirectlySetNewsItemSource,
}
